def eval_sandbox_guard_no_lease_errors():
    """No lease, unknown worker, task mismatch → JSON errors."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)
            ws = registry.durable_worker_store
            ts = registry.durable_task_store

            # Unknown worker
            r1 = registry.call("get_worker_workspace", worker_id="w_nonexistent", task_id="dtask_x")
            p1 = json.loads(r1)
            assert "error" in p1, f"unknown worker should error: {p1}"

            r1v = registry.call("validate_worker_workspace_path", worker_id="w_nonexistent", task_id="dtask_x", path="f.txt")
            p1v = json.loads(r1v)
            assert "error" in p1v, f"unknown worker validate should error: {p1v}"

            # Worker with no lease (assigned but no workspace prepared)
            ws.register_worker("w_nolease", role="coder")
            task_nl = ts.create_task(goal="no lease test", steps=[{"text": "s"}])
            ts.assign_worker(task_nl.task_id, "w_nolease")
            ws.update_status("w_nolease", "assigned", current_task_id=task_nl.task_id)
            ts.update_status(task_nl.task_id, "running")

            r2 = registry.call("get_worker_workspace", worker_id="w_nolease", task_id=task_nl.task_id)
            p2 = json.loads(r2)
            assert "error" in p2, f"no lease should error: {p2}"
            assert "无 workspace lease" in p2["error"], f"error should mention no lease: {p2}"

            r2v = registry.call("validate_worker_workspace_path", worker_id="w_nolease", task_id=task_nl.task_id, path="f.txt")
            p2v = json.loads(r2v)
            assert "error" in p2v, f"no lease validate should error: {p2v}"

            # Task mismatch (worker executing different task)
            ws.register_worker("w_mismatch", role="coder")
            task_a = ts.create_task(goal="task A", steps=[{"text": "s"}])
            task_b = ts.create_task(goal="task B", steps=[{"text": "s"}])
            ts.assign_worker(task_a.task_id, "w_mismatch")
            ws.update_status("w_mismatch", "assigned", current_task_id=task_a.task_id)
            ts.update_status(task_a.task_id, "running")
            # Prepare lease for task_a
            registry.call("prepare_worker_workspace", worker_id="w_mismatch", task_id=task_a.task_id)
            # Now ask about task_b (mismatch)
            r3 = registry.call("get_worker_workspace", worker_id="w_mismatch", task_id=task_b.task_id)
            p3 = json.loads(r3)
            assert "error" in p3, f"task mismatch should error: {p3}"

            r3v = registry.call("validate_worker_workspace_path", worker_id="w_mismatch", task_id=task_b.task_id, path="f.txt")
            p3v = json.loads(r3v)
            assert "error" in p3v, f"task mismatch validate should error: {p3v}"

            # Empty path
            tid, _ = _setup_sandbox_worker_with_lease(registry, worker_id="w_empty")
            r4 = registry.call("validate_worker_workspace_path", worker_id="w_empty", task_id=tid, path="")
            p4 = json.loads(r4)
            assert "error" in p4, f"empty path should error: {p4}"
            assert "不能为空" in p4["error"]
        finally:
            db.close()


def eval_sandbox_guard_offline_idle_rejected():
    """Offline and idle workers with stale current_task_id and lease are rejected."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)
            ws = registry.durable_worker_store
            ts = registry.durable_task_store

            # Setup: worker has lease and current_task_id, then goes offline
            tid_off, ws_path_off = _setup_sandbox_worker_with_lease(registry, worker_id="w_go_offline")
            ws_root_off = Path(ws_path_off)
            abs_path_off = str(ws_root_off / "file.txt")

            # Mark offline while current_task_id and lease remain
            ws.update_status("w_go_offline", "offline", current_task_id=tid_off)

            # get_worker_workspace should reject offline worker
            r1 = registry.call("get_worker_workspace", worker_id="w_go_offline", task_id=tid_off)
            p1 = json.loads(r1)
            assert "error" in p1, f"offline worker should be rejected by get_worker_workspace: {p1}"
            assert "离线" in p1["error"], f"error should mention offline: {p1}"

            # validate_worker_workspace_path should reject offline worker
            r1v = registry.call("validate_worker_workspace_path", worker_id="w_go_offline", task_id=tid_off, path=abs_path_off)
            p1v = json.loads(r1v)
            assert "error" in p1v, f"offline worker should be rejected by validate: {p1v}"
            assert "离线" in p1v["error"], f"error should mention offline: {p1v}"

            # Setup: worker has lease and current_task_id, then goes idle
            tid_idle, ws_path_idle = _setup_sandbox_worker_with_lease(registry, worker_id="w_go_idle")
            ws_root_idle = Path(ws_path_idle)
            abs_path_idle = str(ws_root_idle / "file.txt")

            # Mark idle while current_task_id and lease remain
            ws.update_status("w_go_idle", "idle", current_task_id=tid_idle)

            # get_worker_workspace should reject idle worker
            r2 = registry.call("get_worker_workspace", worker_id="w_go_idle", task_id=tid_idle)
            p2 = json.loads(r2)
            assert "error" in p2, f"idle worker should be rejected by get_worker_workspace: {p2}"
            assert "空闲" in p2["error"], f"error should mention idle: {p2}"

            # validate_worker_workspace_path should reject idle worker
            r2v = registry.call("validate_worker_workspace_path", worker_id="w_go_idle", task_id=tid_idle, path=abs_path_idle)
            p2v = json.loads(r2v)
            assert "error" in p2v, f"idle worker should be rejected by validate: {p2v}"
            assert "空闲" in p2v["error"], f"error should mention idle: {p2v}"
        finally:
            db.close()


def eval_sandbox_guard_safety_no_leak():
    """Sandbox guard output does not leak goal, steps, or secrets."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)
            tid, ws_path = _setup_sandbox_worker_with_lease(registry)

            # get_worker_workspace output
            gw_result = registry.call("get_worker_workspace", worker_id="w_sbox", task_id=tid)
            gw_str = gw_result
            assert _SANDBOX_SENTINEL_GOAL not in gw_str, f"goal leaked in get_worker_workspace: {gw_str}"
            assert _SANDBOX_SENTINEL_SECRET not in gw_str, f"secret leaked in get_worker_workspace: {gw_str}"
            assert _SANDBOX_SENTINEL_STEP not in gw_str, f"step leaked in get_worker_workspace: {gw_str}"
            gw_parsed = json.loads(gw_result)
            for key in ("goal", "steps", "secret"):
                assert key not in gw_parsed, f"get_worker_workspace has forbidden key {key}: {gw_parsed}"

            # validate_worker_workspace_path output (valid path)
            val_result = registry.call(
                "validate_worker_workspace_path",
                worker_id="w_sbox", task_id=tid, path="src/main.py",
            )
            val_str = val_result
            assert _SANDBOX_SENTINEL_GOAL not in val_str, f"goal leaked in validate: {val_str}"
            assert _SANDBOX_SENTINEL_SECRET not in val_str, f"secret leaked in validate: {val_str}"
            assert _SANDBOX_SENTINEL_STEP not in val_str, f"step leaked in validate: {val_str}"
            val_parsed = json.loads(val_result)
            for key in ("goal", "steps", "secret"):
                assert key not in val_parsed, f"validate has forbidden key {key}: {val_parsed}"

            # validate_worker_workspace_path output (error path - traversal)
            err_result = registry.call(
                "validate_worker_workspace_path",
                worker_id="w_sbox", task_id=tid, path="../../etc/passwd",
            )
            err_str = err_result
            assert _SANDBOX_SENTINEL_GOAL not in err_str, f"goal leaked in validate error: {err_str}"
            assert _SANDBOX_SENTINEL_SECRET not in err_str, f"secret leaked in validate error: {err_str}"
            assert _SANDBOX_SENTINEL_STEP not in err_str, f"step leaked in validate error: {err_str}"

            # validate_worker_workspace_path output (error path - no lease)
            ws = registry.durable_worker_store
            ts = registry.durable_task_store
            ws.register_worker("w_noleak", role="coder")
            task_nl = ts.create_task(goal=_SANDBOX_SENTINEL_GOAL, steps=[{"text": _SANDBOX_SENTINEL_STEP}])
            ts.assign_worker(task_nl.task_id, "w_noleak")
            ws.update_status("w_noleak", "assigned", current_task_id=task_nl.task_id)
            ts.update_status(task_nl.task_id, "running")

            nol_result = registry.call(
                "validate_worker_workspace_path",
                worker_id="w_noleak", task_id=task_nl.task_id, path="f.txt",
            )
            nol_str = nol_result
            assert _SANDBOX_SENTINEL_GOAL not in nol_str, f"goal leaked in no-lease error: {nol_str}"
            assert _SANDBOX_SENTINEL_SECRET not in nol_str, f"secret leaked in no-lease error: {nol_str}"
        finally:
            db.close()


def eval_sandbox_guard_error_does_not_break_other_tools():
    """Sandbox guard errors do not break claim/dispatch/list/get worker/task tools."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)
            ws = registry.durable_worker_store
            ts = registry.durable_task_store

            # Trigger sandbox guard errors
            r1 = registry.call("get_worker_workspace", worker_id="w_nonexistent", task_id="dtask_x")
            assert "error" in json.loads(r1)

            r2 = registry.call("validate_worker_workspace_path", worker_id="w_nonexistent", task_id="dtask_x", path="../../etc/passwd")
            assert "error" in json.loads(r2)

            # Existing tools still work after sandbox errors
            # Register worker and create task
            ws.register_worker("w_after_err", role="coder")
            task = ts.create_task(goal="post-error test", steps=[{"text": "s"}])

            # list_workers works
            lw = registry.call("list_workers")
            lw_parsed = json.loads(lw)
            assert isinstance(lw_parsed, list), f"list_workers broken: {lw}"

            # get_worker works
            gw = registry.call("get_worker", worker_id="w_after_err")
            gw_parsed = json.loads(gw)
            assert gw_parsed.get("worker_id") == "w_after_err", f"get_worker broken: {gw}"

            # list_durable_tasks works
            lt = registry.call("list_durable_tasks")
            lt_parsed = json.loads(lt)
            assert isinstance(lt_parsed, list), f"list_durable_tasks broken: {lt}"

            # get_durable_task works
            gt = registry.call("get_durable_task", task_id=task.task_id)
            gt_parsed = json.loads(gt)
            assert gt_parsed.get("task_id") == task.task_id, f"get_durable_task broken: {gt}"

            # claim still works
            claim_r = registry.call("claim_durable_task", worker_id="w_after_err")
            claim_parsed = json.loads(claim_r)
            assert claim_parsed.get("claimed") is True, f"claim broken after sandbox errors: {claim_r}"

            # Validate still works after successful claim — use absolute path inside workspace
            tid = claim_parsed.get("task_id")
            ws_info = claim_parsed.get("workspace", {})
            ws_path = ws_info.get("workspace_path", "")
            assert ws_path, f"claim should produce workspace_path: {claim_r}"
            abs_test_path = str(Path(ws_path) / "test.txt")
            val_r = registry.call("validate_worker_workspace_path", worker_id="w_after_err", task_id=tid, path=abs_test_path)
            val_parsed = json.loads(val_r)
            assert val_parsed.get("valid") is True, f"validate should succeed with absolute path inside workspace: {val_r}"
        finally:
            db.close()


# --- Checkpoint eval sentinels ---

_CHECKPOINT_SENTINEL_GOAL = "NORA_EVAL_CHECKPOINT_GOAL_SENTINEL_e5f6a7b8"
_CHECKPOINT_SENTINEL_SECRET = "NORA_EVAL_CHECKPOINT_SECRET_sk-ckpt-9a0b1c2d"
_CHECKPOINT_SENTINEL_DESC = "NORA_EVAL_CHECKPOINT_DESC_SENTINEL_3e4f5a6b"
_CHECKPOINT_SENTINEL_SUMMARY = "NORA_EVAL_CHECKPOINT_SUMMARY_SENTINEL_7c8d9e0f"


def eval_checkpoint_basics():
    """add_durable_checkpoint increments count, returns bounded JSON with task_id/checkpoint_id/step_id/count/presence flags."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)

            create_r = registry.call("create_durable_task", goal="checkpoint test", steps="step one\nstep two")
            task_id = json.loads(create_r)["task_id"]

            # First checkpoint
            r1 = registry.call("add_durable_checkpoint", task_id=task_id, step_id=1, description="mid-task snapshot", state_summary="progress 50%")
            p1 = json.loads(r1)
            assert p1["task_id"] == task_id, f"task_id: {p1}"
            assert p1["checkpoint_id"], f"missing checkpoint_id: {p1}"
            assert p1["step_id"] == 1, f"step_id: {p1}"
            assert p1["checkpoint_count"] == 1, f"count: {p1}"
            assert p1["description_present"] is True, f"description_present: {p1}"
            assert p1["state_summary_present"] is True, f"state_summary_present: {p1}"
            # Bounded: no raw text fields
            for key in ("description", "state_summary", "goal", "steps", "raw_description"):
                assert key not in p1, f"output has {key}: {p1}"

            # Second checkpoint — count increments
            r2 = registry.call("add_durable_checkpoint", task_id=task_id, step_id=2)
            p2 = json.loads(r2)
            assert p2["checkpoint_count"] == 2, f"count after 2nd: {p2}"
            assert p2["description_present"] is False
            assert p2["state_summary_present"] is False

            # Unknown task returns error
            r3 = registry.call("add_durable_checkpoint", task_id="dtask_nonexistent")
            assert "error" in json.loads(r3), f"unknown task: {r3}"

            # get_durable_task includes checkpoints
            detail_r = registry.call("get_durable_task", task_id=task_id)
            detail = json.loads(detail_r)
            assert len(detail["checkpoints"]) == 2, f"checkpoint count in detail: {len(detail['checkpoints'])}"
        finally:
            db.close()


def eval_checkpoint_step_consistency():
    """Matching step gets checkpoint_ref; existing checkpoints/trace_refs preserved; bad step_id bounded."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)
            ts = registry.durable_task_store

            create_r = registry.call("create_durable_task", goal="step ref test", steps="alpha\nbeta\ngamma")
            task_id = json.loads(create_r)["task_id"]

            # Add checkpoint for step 1
            r1 = registry.call("add_durable_checkpoint", task_id=task_id, step_id=1)
            cp1_id = json.loads(r1)["checkpoint_id"]

            # Step 1 should have checkpoint_ref
            task = ts.get_task(task_id)
            step1 = next(s for s in task.steps if s.id == 1)
            assert step1.checkpoint_ref == cp1_id, f"step1 checkpoint_ref: {step1.checkpoint_ref}"

            # Step 2 should not have checkpoint_ref
            step2 = next(s for s in task.steps if s.id == 2)
            assert step2.checkpoint_ref is None, f"step2 should not have ref: {step2.checkpoint_ref}"

            # Add checkpoint for step 2 — step 1's ref preserved
            r2 = registry.call("add_durable_checkpoint", task_id=task_id, step_id=2)
            cp2_id = json.loads(r2)["checkpoint_id"]
            task = ts.get_task(task_id)
            step1 = next(s for s in task.steps if s.id == 1)
            step2 = next(s for s in task.steps if s.id == 2)
            assert step1.checkpoint_ref == cp1_id, f"step1 ref changed: {step1.checkpoint_ref}"
            assert step2.checkpoint_ref == cp2_id, f"step2 ref: {step2.checkpoint_ref}"

            # Existing trace_refs preserved
            task.trace_refs.append("trace_existing")
            ts.upsert_task(task)
            registry.call("add_durable_checkpoint", task_id=task_id, step_id=3)
            task = ts.get_task(task_id)
            assert "trace_existing" in task.trace_refs, f"trace_refs lost: {task.trace_refs}"

            # Bad step_id (non-integer) returns error
            r_bad = registry.call("add_durable_checkpoint", task_id=task_id, step_id="not_a_number")
            assert "error" in json.loads(r_bad), f"bad step_id: {r_bad}"

            # Large step_id is clamped/bounded (no crash, checkpoint created with max(0, step_id))
            r_large = registry.call("add_durable_checkpoint", task_id=task_id, step_id=999)
            p_large = json.loads(r_large)
            assert "checkpoint_id" in p_large, f"large step_id crashed: {p_large}"
            assert p_large["step_id"] == 999, f"step_id clamped: {p_large}"
        finally:
            db.close()


def eval_checkpoint_event_coverage():
    """CHECKPOINT_ADDED event recorded with safe metadata. No raw goal/step text/description/summary/secrets in payload."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)

            create_r = registry.call("create_durable_task", goal=_CHECKPOINT_SENTINEL_GOAL, steps="secret step text")
            task_id = json.loads(create_r)["task_id"]

            registry.call("add_durable_checkpoint", task_id=task_id, step_id=0, description=_CHECKPOINT_SENTINEL_DESC, state_summary=_CHECKPOINT_SENTINEL_SUMMARY)

            events = registry.durable_event_store.list_events(task_id=task_id)
            cp_events = [e for e in events if e.event_type == CHECKPOINT_ADDED]
            assert len(cp_events) >= 1, f"no checkpoint event: {[e.event_type for e in events]}"

            cp_event = cp_events[0]
            assert cp_event.severity == "info", f"severity: {cp_event.severity}"
            assert cp_event.payload.get("operation") == "checkpoint"
            assert cp_event.payload.get("checkpoint_id"), f"missing checkpoint_id in payload"
            assert cp_event.payload.get("step_id") == 0
            assert cp_event.payload.get("checkpoint_count") >= 1

            # Sentinel safety: no raw goal, description, summary, or secrets in serialized event
            serialized = json.dumps(cp_event.to_dict(), ensure_ascii=False)
            assert _CHECKPOINT_SENTINEL_GOAL not in serialized, "goal leaked in event"
            assert _CHECKPOINT_SENTINEL_DESC not in serialized, "raw description leaked in event"
            assert _CHECKPOINT_SENTINEL_SUMMARY not in serialized, "raw state_summary leaked in event"
            assert "secret step text" not in serialized, "raw step text leaked in event"
        finally:
            db.close()


def eval_checkpoint_safety_failure_isolation():
    """Sentinel safety in output. Broken event store doesn't prevent checkpoint. Registry tools still work."""
    class BrokenEventStore:
        def record(self, **kwargs):
            raise RuntimeError("event store offline")
        def list_events(self, **kwargs):
            return []

    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)

            # Sentinel safety in output
            create_r = registry.call("create_durable_task", goal=_CHECKPOINT_SENTINEL_GOAL, steps="s")
            task_id = json.loads(create_r)["task_id"]
            r = registry.call("add_durable_checkpoint", task_id=task_id, description=_CHECKPOINT_SENTINEL_DESC, state_summary=_CHECKPOINT_SENTINEL_SECRET)
            assert _CHECKPOINT_SENTINEL_GOAL not in r, "goal leaked in output"
            assert _CHECKPOINT_SENTINEL_DESC not in r, "raw description leaked in output"
            assert _CHECKPOINT_SENTINEL_SECRET not in r, "raw state_summary leaked in output"

            # Broken event store: checkpoint must still work
            registry.durable_event_store = BrokenEventStore()
            r2 = registry.call("add_durable_checkpoint", task_id=task_id)
            p2 = json.loads(r2)
            assert "checkpoint_id" in p2, f"checkpoint failed with broken store: {p2}"
            assert p2["checkpoint_count"] >= 1

            # Existing registry tools still work
            assert "error" not in json.loads(registry.call("get_durable_task", task_id=task_id))
            assert isinstance(json.loads(registry.call("list_durable_tasks")), list)
        finally:
            db.close()


# --- Recovery plan eval sentinels ---

_RECOVERY_SENTINEL_GOAL = "NORA_EVAL_RECOVERY_GOAL_SENTINEL_a9b8c7d6"
_RECOVERY_SENTINEL_STEP = "NORA_EVAL_RECOVERY_STEP_SECRET_e5f4a3b2"
_RECOVERY_SENTINEL_SECRET = "NORA_EVAL_RECOVERY_SECRET_sk-recovery-c1d2e3f4"


def eval_recovery_plan_basics():
    """plan_durable_recovery returns correct selected checkpoint, resume_policy, next_step_id, counts, can_resume."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)

            # Create task with 3 steps
            create_r = registry.call("create_durable_task", goal="recovery test", steps="alpha\nbeta\ngamma")
            task_id = json.loads(create_r)["task_id"]

            # Add checkpoint for step 1
            cp1_r = registry.call("add_durable_checkpoint", task_id=task_id, step_id=1, description="after alpha")
            cp1_id = json.loads(cp1_r)["checkpoint_id"]

            # Add checkpoint for step 2
            cp2_r = registry.call("add_durable_checkpoint", task_id=task_id, step_id=2, description="after beta")
            cp2_id = json.loads(cp2_r)["checkpoint_id"]

            # Plan with latest checkpoint (default)
            plan_r = registry.call("plan_durable_recovery", task_id=task_id)
            plan = json.loads(plan_r)
            assert plan["task_id"] == task_id
            assert plan["can_resume"] is True, f"can_resume: {plan}"
            assert plan["selected_checkpoint_id"] == cp2_id, f"selected: {plan}"
            assert plan["checkpoint_step_id"] == 2, f"cp step: {plan}"
            assert plan["resume_policy"] == "from_checkpoint", f"policy: {plan}"
            assert plan["checkpoint_count"] == 2, f"cp count: {plan}"
            assert plan["step_count"] == 3, f"step count: {plan}"
            assert plan["incomplete_step_count"] == 3, f"incomplete: {plan}"
            assert plan["reason"] == "checkpoint_selected", f"reason: {plan}"

            # Bounded output: no raw fields
            for key in ("goal", "steps", "description", "state_snapshot", "notes"):
                assert key not in plan, f"output has {key}: {plan}"

            # Mark step 1 done, re-plan: latest checkpoint is step 2 (not done),
            # so next_step_id must be 2 (the checkpoint step is incomplete).
            ts = registry.durable_task_store
            task = ts.get_task(task_id)
            task.steps[0].status = "done"
            ts.upsert_task(task)
            plan_r2 = registry.call("plan_durable_recovery", task_id=task_id)
            plan2 = json.loads(plan_r2)
            assert plan2["incomplete_step_count"] == 2
            assert plan2["next_step_id"] == 2, f"next_step must be 2 (checkpoint step not done): {plan2}"
        finally:
            db.close()


def eval_recovery_plan_selection_fallback():
    """Explicit checkpoint_id, step_id, missing step checkpoint, no-checkpoint, unknown task/checkpoint, bad step_id."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
        try:
            registry = build_default_registry(workspace_root=Path(tmpdir), db=db, confirm_action=lambda _: True)

            create_r = registry.call("create_durable_task", goal="fallback test", steps="s1\ns2")
            task_id = json.loads(create_r)["task_id"]
            cp1_r = registry.call("add_durable_checkpoint", task_id=task_id, step_id=1)
            cp1_id = json.loads(cp1_r)["checkpoint_id"]
            cp2_r = registry.call("add_durable_checkpoint", task_id=task_id, step_id=2)
            cp2_id = json.loads(cp2_r)["checkpoint_id"]

            # Explicit checkpoint_id selection
            plan_explicit = json.loads(registry.call("plan_durable_recovery", task_id=task_id, checkpoint_id=cp1_id))
            assert plan_explicit["selected_checkpoint_id"] == cp1_id, f"explicit: {plan_explicit}"
            assert plan_explicit["checkpoint_step_id"] == 1
            assert plan_explicit["reason"] == "checkpoint_selected"

            # step_id selection (latest checkpoint for that step)
            plan_step = json.loads(registry.call("plan_durable_recovery", task_id=task_id, step_id="2"))
            assert plan_step["selected_checkpoint_id"] == cp2_id, f"step selection: {plan_step}"
            assert plan_step["reason"] == "checkpoint_selected"

            # Missing step checkpoint fallback (step with no checkpoint)
            create_r2 = registry.call("create_durable_task", goal="no cp step", steps="a\nb")
            tid2 = json.loads(create_r2)["task_id"]
            registry.call("add_durable_checkpoint", task_id=tid2, step_id=1)
            plan_missing = json.loads(registry.call("plan_durable_recovery", task_id=tid2, step_id="999"))
            assert plan_missing["selected_checkpoint_id"] is None, f"missing step: {plan_missing}"
            assert plan_missing["reason"] == "step_checkpoint_missing", f"reason: {plan_missing}"

            # No-checkpoint fallback
            create_r3 = registry.call("create_durable_task", goal="no checkpoint", steps="x")
            tid3 = json.loads(create_r3)["task_id"]
            plan_none = json.loads(registry.call("plan_durable_recovery", task_id=tid3))
            assert plan_none["selected_checkpoint_id"] is None, f"no cp: {plan_none}"
            assert plan_none["reason"] == "no_checkpoint", f"reason: {plan_none}"
            assert plan_none["can_resume"] is True

            # Unknown task
            r_unknown = json.loads(registry.call("plan_durable_recovery", task_id="dtask_nonexistent"))
            assert "error" in r_unknown, f"unknown task: {r_unknown}"

            # Unknown checkpoint
            r_bad_cp = json.loads(registry.call("plan_durable_recovery", task_id=task_id, checkpoint_id="cp_nonexistent"))
            assert "error" in r_bad_cp, f"unknown checkpoint: {r_bad_cp}"

            # Bad step_id
            r_bad_step = json.loads(registry.call("plan_durable_recovery", task_id=task_id, step_id="not_a_number"))
            assert "error" in r_bad_step, f"bad step_id: {r_bad_step}"

            # Terminal status: can_resume = False
            registry.call("update_durable_task", task_id=task_id, status="running")
            registry.call("update_durable_task", task_id=task_id, status="completed")
            plan_terminal = json.loads(registry.call("plan_durable_recovery", task_id=task_id))
            assert plan_terminal["can_resume"] is False, f"terminal can_resume: {plan_terminal}"
            assert plan_terminal["reason"] == "terminal_status", f"terminal reason: {plan_terminal}"
        finally:
            db.close()


def eval_recovery_plan_safety():
    """No raw goals, step text, notes, summaries, checkpoint descriptions, state_snapshot, or secrets in output."""
    with tempfile.TemporaryDirectory() as tmpdir:
        db = NoraDB(Path(tmpdir) / "test.db")
